package com.game.combodetector.headless;

import com.badlogic.gdx.Input.Keys;

public class KeyMapper {
    public static int getKeyCode(String keyName) {
        switch (keyName) {
            case "UP": return Keys.UP;
            case "DOWN": return Keys.DOWN;
            case "LEFT": return Keys.LEFT;
            case "RIGHT": return Keys.RIGHT;
            case "PUNCH": return Keys.X;
            case "KICK": return Keys.Z;
            case "PAUSE": return Keys.P;
            default: return -1;
        }
    }
}

package com.game.combodetector.headless;

import com.badlogic.gdx.InputProcessor;
import com.badlogic.gdx.backends.headless.mock.input.MockInput;
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class ReplayInput extends MockInput {
    private InputProcessor processor;
    private final List<String> lines = new ArrayList<>();
    private int currentTick = 0;
    private final Set<Integer> pressedKeys = new HashSet<>();

    public ReplayInput(String inputFilePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(inputFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                lines.add(line);
            }
        }
    }

    @Override
    public void setInputProcessor(InputProcessor processor) {
        this.processor = processor;
    }

    @Override
    public InputProcessor getInputProcessor() {
        return this.processor;
    }

    public boolean hasMoreTicks() {
        return currentTick < lines.size();
    }

    public int getCurrentTick() {
        return currentTick;
    }

    public void tick() {
        if (!hasMoreTicks()) {
            return;
        }
        String line = lines.get(currentTick);
        String trimmed = line.trim();
        if (!trimmed.isEmpty()) {
            String[] tokens = trimmed.split("\\s+");
            for (String token : tokens) {
                if (token.isEmpty()) continue;
                char sign = token.charAt(0);
                String keyName = token.substring(1);
                int keycode = KeyMapper.getKeyCode(keyName);
                if (keycode != -1) {
                    if (sign == '+') {
                        pressedKeys.add(keycode);
                        if (processor != null) {
                            processor.keyDown(keycode);
                        }
                    } else if (sign == '-') {
                        pressedKeys.remove(keycode);
                        if (processor != null) {
                            processor.keyUp(keycode);
                        }
                    }
                }
            }
        }
        currentTick++;
    }

    @Override
    public boolean isKeyPressed(int key) {
        return pressedKeys.contains(key);
    }
}

package com.game.combodetector.headless;

import com.badlogic.gdx.InputAdapter;
import com.badlogic.gdx.Input.Keys;

public class PauseProcessor extends InputAdapter {
    private boolean paused = false;

    public boolean isPaused() {
        return paused;
    }

    @Override
    public boolean keyDown(int keycode) {
        if (keycode == Keys.P) { // PAUSE
            paused = !paused;
            return true;
        }
        if (paused) {
            return true;
        }
        return false;
    }

    @Override
    public boolean keyUp(int keycode) {
        if (keycode == Keys.P) { // PAUSE
            return true;
        }
        if (paused) {
            return true;
        }
        return false;
    }
}

package com.game.combodetector.headless;

import com.badlogic.gdx.InputAdapter;
import com.badlogic.gdx.Input.Keys;
import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class ComboProcessor extends InputAdapter {
    public static class DirectionToken {
        public final int direction;
        public final int tick;

        public DirectionToken(int direction, int tick) {
            this.direction = direction;
            this.tick = tick;
        }

        @Override
        public String toString() {
            return "(" + direction + ", " + tick + ")";
        }
    }

    public static class Combo {
        public final String name;
        public final int buttonKey;
        public final int[] motion;

        public Combo(String name, int buttonKey, int[] motion) {
            this.name = name;
            this.buttonKey = buttonKey;
            this.motion = motion;
        }
    }

    private final ReplayInput replayInput;
    private final List<Combo> combos = List.of(
        new Combo("HADOKEN", Keys.X, new int[]{2, 3, 6}),
        new Combo("SHORYUKEN", Keys.X, new int[]{6, 2, 3}),
        new Combo("TATSU", Keys.Z, new int[]{2, 1, 4})
    );

    private final List<DirectionToken> directionBuffer = new ArrayList<>();
    private final List<String> recognizedLog = new ArrayList<>();
    private final int[] tally = new int[3]; // HADOKEN=0, SHORYUKEN=1, TATSU=2
    private int totalCount = 0;

    private int lastDirection = 5;

    // Held state for directional keys
    private boolean upHeld = false;
    private boolean downHeld = false;
    private boolean leftHeld = false;
    private boolean rightHeld = false;

    public ComboProcessor(ReplayInput replayInput) {
        this.replayInput = replayInput;
    }

    private boolean isDirectionalKey(int keycode) {
        return keycode == Keys.UP || keycode == Keys.DOWN || keycode == Keys.LEFT || keycode == Keys.RIGHT;
    }

    private void updateHeldState(int keycode, boolean pressed) {
        if (keycode == Keys.UP) upHeld = pressed;
        else if (keycode == Keys.DOWN) downHeld = pressed;
        else if (keycode == Keys.LEFT) leftHeld = pressed;
        else if (keycode == Keys.RIGHT) rightHeld = pressed;
    }

    private int computeDirection() {
        int h = 0;
        if (leftHeld && !rightHeld) h = -1;
        else if (rightHeld && !leftHeld) h = 1;

        int v = 0;
        if (upHeld && !downHeld) v = 1;
        else if (downHeld && !upHeld) v = -1;

        if (h == -1 && v == -1) return 1;
        if (h == 0 && v == -1) return 2;
        if (h == 1 && v == -1) return 3;
        if (h == -1 && v == 0) return 4;
        if (h == 0 && v == 0) return 5;
        if (h == 1 && v == 0) return 6;
        if (h == -1 && v == 1) return 7;
        if (h == 0 && v == 1) return 8;
        if (h == 1 && v == 1) return 9;
        return 5;
    }

    private boolean handleButtonDown(int keycode, int currentTick) {
        // Filter directionBuffer for T - t <= 12
        List<DirectionToken> B = new ArrayList<>();
        for (DirectionToken token : directionBuffer) {
            if (currentTick - token.tick <= 12) {
                B.add(token);
            }
        }

        // Check combos in priority order
        for (int comboIdx = 0; comboIdx < combos.size(); comboIdx++) {
            Combo combo = combos.get(comboIdx);
            if (combo.buttonKey == keycode) {
                int k = combo.motion.length;
                if (B.size() >= k) {
                    boolean match = true;
                    for (int i = 0; i < k; i++) {
                        if (B.get(B.size() - k + i).direction != combo.motion[i]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        // Recognized!
                        recognizedLog.add("TICK " + currentTick + " " + combo.name);
                        tally[comboIdx]++;
                        totalCount++;
                        directionBuffer.clear();
                        return true; // consumes the event
                    }
                }
            }
        }

        return false;
    }

    @Override
    public boolean keyDown(int keycode) {
        int currentTick = replayInput.getCurrentTick();

        if (isDirectionalKey(keycode)) {
            updateHeldState(keycode, true);
            int d = computeDirection();
            if (d != lastDirection) {
                if (d != 5) {
                    directionBuffer.add(new DirectionToken(d, currentTick));
                }
                lastDirection = d;
            }
            return false; // direction events never consume
        }

        if (keycode == Keys.X || keycode == Keys.Z) {
            return handleButtonDown(keycode, currentTick);
        }

        return false;
    }

    @Override
    public boolean keyUp(int keycode) {
        int currentTick = replayInput.getCurrentTick();

        if (isDirectionalKey(keycode)) {
            updateHeldState(keycode, false);
            int d = computeDirection();
            if (d != lastDirection) {
                if (d != 5) {
                    directionBuffer.add(new DirectionToken(d, currentTick));
                }
                lastDirection = d;
            }
            return false; // direction events never consume
        }

        return false;
    }

    public void writeResults(String outputFilePath) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFilePath))) {
            for (String logLine : recognizedLog) {
                writer.write(logLine);
                writer.write("\n");
            }
            writer.write("--- TALLY ---\n");
            writer.write("HADOKEN " + tally[0] + "\n");
            writer.write("SHORYUKEN " + tally[1] + "\n");
            writer.write("TATSU " + tally[2] + "\n");
            writer.write("TOTAL " + totalCount + "\n");
        }
    }
}

package com.game.combodetector.headless;

import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.InputMultiplexer;
import java.io.IOException;
import java.util.concurrent.CountDownLatch;

public class ComboDetectorGame implements ApplicationListener {
    private final String inputFilePath;
    private final String outputFilePath;
    private final CountDownLatch latch;

    private ReplayInput replayInput;
    private PauseProcessor pauseProcessor;
    private ComboProcessor comboProcessor;

    public ComboDetectorGame(String inputFilePath, String outputFilePath, CountDownLatch latch) {
        this.inputFilePath = inputFilePath;
        this.outputFilePath = outputFilePath;
        this.latch = latch;
    }

    @Override
    public void create() {
        try {
            replayInput = new ReplayInput(inputFilePath);
            Gdx.input = replayInput;

            pauseProcessor = new PauseProcessor();
            comboProcessor = new ComboProcessor(replayInput);

            InputMultiplexer multiplexer = new InputMultiplexer();
            multiplexer.addProcessor(pauseProcessor);
            multiplexer.addProcessor(comboProcessor);

            replayInput.setInputProcessor(multiplexer);

        } catch (Exception e) {
            e.printStackTrace();
            latch.countDown();
            Gdx.app.exit();
        }
    }

    @Override
    public void resize(int width, int height) {}

    @Override
    public void render() {
        if (replayInput != null && replayInput.hasMoreTicks()) {
            replayInput.tick();
        } else {
            writeOutputAndExit();
        }
    }

    private void writeOutputAndExit() {
        try {
            if (comboProcessor != null) {
                comboProcessor.writeResults(outputFilePath);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            latch.countDown();
            Gdx.app.exit();
        }
    }

    @Override
    public void pause() {}

    @Override
    public void resume() {}

    @Override
    public void dispose() {}
}

package com.game.combodetector.headless;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;
import java.util.concurrent.CountDownLatch;

public class HeadlessLauncher {
    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: HeadlessLauncher <input_file> <output_file>");
            System.exit(1);
        }
        String inputFile = args[0];
        String outputFile = args[1];

        CountDownLatch latch = new CountDownLatch(1);
        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        config.updatesPerSecond = 0; // run as fast as possible, never sleep

        ComboDetectorGame game = new ComboDetectorGame(inputFile, outputFile, latch);
        new HeadlessApplication(game, config);

        try {
            latch.await();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
